from pathlib import Path
from unittest.mock import patch
from contextlib import redirect_stdout
import copy, hashlib, io, json, sys
root=Path.cwd();sys.path.insert(0,str(root/'scripts'))
import replay_window_signals as replay
import generate_window_signals as generator
stage=root/'research_runs/agent_research/intervention_diagnosis/20261018_measurement_generation_r4'
base=stage.parent
call_names=[f'{f}_{m}' for f in ('ETT','Hydraulic') for m in ('ordinary','mismatch')]
filenames=('response.json','receipt.json','prompt.txt','events.jsonl')
class GateReached(Exception):pass

def probe(kind,mutation=None):
    hashes={str(stage/'evaluation_lock.json'):'evaluation',str(stage/'PROTOCOL.md'):'protocol',str(stage/'generation/generation_lock.json'):'generation'}
    scripts={name:'code_'+name for name in generator.SCRIPTS}
    hashes.update({str(root/'scripts'/name):value for name,value in scripts.items()})
    tables={name:'table_'+name for name in ('ETT_ETTh1.npz','ETT_ETTh2.npz','Hydraulic_G1.npz','Hydraulic_G2.npz','Hydraulic_G3.npz')}
    hashes.update({str(base/'20261018_parent_measurements_r3/frequency_corrected'/name):value for name,value in tables.items()})
    pool=base/'20261018_conditional_diagnosis_r1/development_pool.json';hashes[str(pool)]='pool'
    reads={};calls={};entries=[]
    for name in call_names:
        values={filename:name+'_'+filename for filename in filenames};calls[name]=values
        folder=stage/'generation'/name
        hashes.update({str(folder/filename):value for filename,value in values.items()})
        reads[str(folder/'receipt.json')]={'status':'PASS','response_sha256':values['response.json']}
        entries.append({'name':name,'prompt_sha256':values['prompt.txt']})
    reads[str(stage/'evaluation_lock.json')]={'script_sha256':scripts,'table_sha256':tables,'protocol_sha256':'protocol','pool_sha256':'pool'}
    reads[str(stage/'generated_outputs_lock.json')]={'evaluation_lock_sha256':'evaluation','generation_lock_sha256':'generation','calls':calls}
    reads[str(stage/'generation/generation_lock.json')]={'evaluation_lock_sha256':'evaluation','script_sha256':scripts,'protocol_sha256':'protocol','calls':entries}
    if mutation:mutation(reads,hashes)
    writes=[]
    def fake_read(path):
        if Path(path)==pool:raise GateReached()
        return copy.deepcopy(reads[str(path)])
    def fake_sha(path):
        if str(path) not in hashes:raise FileNotFoundError(str(path))
        return hashes[str(path)]
    module=replay if kind=='replay' else generator
    try:
        with patch.object(module,'read',fake_read),patch.object(module,'sha',fake_sha),patch.object(module,'write',lambda p,v:writes.append((str(p),v))),redirect_stdout(io.StringIO()):
            module.main() if kind=='replay' else module.seal()
    except GateReached:return 'gate_passed',len(writes)
    except (AssertionError,FileNotFoundError) as exc:return type(exc).__name__,len(writes)
    return 'sealed',len(writes)

assert probe('replay')==('gate_passed',0)
assert probe('seal')==('sealed',1)
checks=[]
mutations=[
('empty generation calls at seal','seal',lambda r,h:r[str(stage/'generation/generation_lock.json')].__setitem__('calls',[])),
('empty output calls at replay','replay',lambda r,h:r[str(stage/'generated_outputs_lock.json')].__setitem__('calls',{})),
('changed generation lock association','replay',lambda r,h:h.__setitem__(str(stage/'generation/generation_lock.json'),'changed')),
]
for filename in filenames:
    mutations.append((f'missing output manifest file: {filename}','replay',lambda r,h,f=filename:r[str(stage/'generated_outputs_lock.json')]['calls']['ETT_ordinary'].pop(f)))
mutations.append(('missing physical events file at seal','seal',lambda r,h:h.pop(str(stage/'generation/ETT_ordinary/events.jsonl'))))
mutations.append(('missing physical events file at replay','replay',lambda r,h:h.pop(str(stage/'generation/ETT_ordinary/events.jsonl'))))
for label,kind,mutation in mutations:
    outcome,writes=probe(kind,mutation)
    assert outcome in ('AssertionError','FileNotFoundError') and writes==0,(label,outcome,writes)
    checks.append({'case':label,'runner':kind,'status':'PASS','actual':outcome,'writes':writes})
path=stage/'interface_lock_resolution.json'
old=json.loads(path.read_text(encoding='utf-8-sig')) if path.exists() else {}
result={'status':'PASS','audit_completion':'complete','scope':'Only empty call lists, missing manifest/physical files, and changed generation-lock association; two valid-fixture sanity checks.','checks':checks,'positive_fixture_sanity':{'replay':'reaches pool boundary only','seal':'one in-memory output lock write'},'resolved_findings':['reproduced_lock_schema_gap','reproduced_unchecked_lock_link'],'reviewed_locations':['scripts/generate_window_signals.py:78','scripts/replay_window_signals.py:98-102'],'script_sha256':{name:hashlib.sha256((root/'scripts'/name).read_bytes()).hexdigest() for name in ('replay_window_signals.py','generate_window_signals.py')},'limitations':['Runtime tests use in-memory read/sha/write fixtures, not actual generation outputs.','No previous 22 hash-tampering checks, 23 expression checks, 9 matrices or 14 method checks repeated.','No LLM calls, strategy execution, training, or D/test access.'],'command':'Run stored probe_source with python -c in PowerShell 7 from project root.'}
if 'probe_source' in old:result['probe_source']=old['probe_source']
path.write_text(json.dumps(result,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
print(json.dumps({'status':'PASS','targeted_rejections':len(checks),'sanity_checks':2,'writes_in_rejected_cases':0}))
